83	    (0x1FBF0, 0x1FBF9),
84	];
85	
86	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
87	enum Action {
88	    Help,
89	    Format,
90	    Top,
91	    Json,
92	    Strict,
93	}
94	
95	impl Action {
96	    fn takes_value(self) -> bool {
97	        matches!(self, Action::Format | Action::Top)
98	    }
99	}
100	
101	fn action_for(name: &str) -> Option<Action> {
102	    match name {
103	        "-h" | "--help" => Some(Action::Help),
104	        "--format" => Some(Action::Format),
105	        "--top" => Some(Action::Top),
106	        "--json" => Some(Action::Json),
107	        "--strict" => Some(Action::Strict),
108	        _ => None,
109	    }
110	}
111	
112	#[derive(Debug, PartialEq, Eq)]
113	pub struct Args {
114	    pub file: OsString,
115	    pub format: Option<Format>,
116	    pub top: u64,
117	    pub json: bool,
118	    pub strict: bool,
119	}
120	
121	#[derive(Debug, PartialEq, Eq)]
122	pub enum Outcome {
123	    Run(Args),
124	    /// 도움말을 stdout 에 쓰고 종료 0
125	    Help,
126	    /// 인자 오류, 종료 2
127	    Error(String),
128	}
129	
130	/// `_parse_optional` 의 결과 중 옵션인 경우
131	#[derive(Debug, Clone)]
132	struct OptTuple {
133	    /// None 이면 알 수 없는 옵션
134	    action: Option<Action>,
135	    option: String,
136	    /// `=` 로 나뉘었는가
137	    sep: bool,
138	    explicit: Option<String>,
139	}
140	
141	fn is_decimal(c: char) -> bool {
142	    decimal_value(c).is_some()
143	}
144	
145	/// `Py_UNICODE_TODECIMAL`. 모든 10진 숫자 블록은 0부터 시작하는 10자 묶음이다(verify/int_charsets.py)
146	pub(crate) fn decimal_value(c: char) -> Option<u32> {
147	    let c = c as u32;
148	    DECIMAL_RANGES
149	        .iter()
150	        .find(|&&(a, b)| (a..=b).contains(&c))
151	        .map(|&(a, _)| (c - a) % 10)
152	}
153	
154	/// `^-\d+$|^-\d*\.\d+$` (`$` 는 끝의 개행 하나 앞에서도 맞는다)
155	fn looks_negative(arg: &str) -> bool {
156	    let Some(body) = arg.strip_prefix('-') else {
157	        return false;
158	    };
159	    let body = body.strip_suffix('\n').unwrap_or(body);
160	    let digits = |s: &str| !s.is_empty() && s.chars().all(is_decimal);
161	    match body.split_once('.') {
162	        None => digits(body),
163	        Some((int, frac)) => (int.is_empty() || int.chars().all(is_decimal)) && digits(frac),
164	    }
165	}
166	
167	/// None 이면 위치 인자
168	fn classify(arg: &str) -> Option<OptTuple> {
169	    if !arg.starts_with('-') {
170	        return None;
171	    }
172	    if let Some(action) = action_for(arg) {
173	        return Some(OptTuple {
174	            action: Some(action),
175	            option: arg.to_string(),
176	            sep: false,
177	            explicit: None,
178	        });
179	    }
180	    if arg.chars().count() == 1 {
181	        return None;
182	    }
183	    if let Some((name, value)) = arg.split_once('=') {
184	        if let Some(action) = action_for(name) {
185	            return Some(OptTuple {
186	                action: Some(action),
187	                option: name.to_string(),
188	                sep: true,
189	                explicit: Some(value.to_string()),
190	            });
191	        }
192	    }
193	    // allow_abbrev=False 라도 한 글자 옵션(-h) 뒤에 붙은 글자는 나눠 본다
194	    if !arg.starts_with("--") {
195	        if let Some(rest) = arg.strip_prefix("-h") {
196	            return Some(OptTuple {
197	                action: Some(Action::Help),
198	                option: "-h".to_string(),
199	                sep: false,
200	                explicit: Some(rest.to_string()),
201	            });
202	        }
203	    }
204	    if looks_negative(arg) || arg.contains(' ') {
205	        return None;
206	    }
207	    Some(OptTuple {
208	        action: None,
209	        option: arg.to_string(),
210	        sep: false,
211	        explicit: None,
212	    })
213	}
214	
215	#[derive(Clone, Copy, PartialEq, Eq)]
216	enum Pattern {
217	    /// 인자
218	    A,
219	    /// 옵션
220	    O,
221	    /// 처음 나온 `--`
222	    DashDash,
223	}
224	
225	enum Stop {
226	    Help,
227	    Error(String),
228	}
229	
230	fn positive_int(value: &str) -> Result<u64, String> {
231	    // int() 는 4300자리(앞의 0 포함)가 넘으면 ValueError
232	    if value.is_empty()
233	        || !value.bytes().all(|b| b.is_ascii_digit())
234	        || value.len() > 4300
235	        || value.bytes().all(|b| b == b'0')
236	    {
237	        return Err(format!(
238	            "argument --top: invalid positive_int value: '{value}'"
239	        ));
240	    }
241	    Ok(value.parse::<u64>().unwrap_or(u64::MAX))
242	}
243	
244	struct State<'a> {
245	    args: &'a [OsString],
246	    pattern: Vec<Pattern>,
247	    tuples: Vec<Option<OptTuple>>,
248	    file: Option<OsString>,
249	    format: Option<Format>,
250	    top: u64,
251	    json: bool,
252	    strict: bool,
253	    extras: bool,
254	}
255	
256	impl State<'_> {
257	    fn take_action(&mut self, action: Action, value: Option<String>) -> Result<(), Stop> {
258	        let value = value.unwrap_or_default();
259	        match action {
260	            Action::Help => return Err(Stop::Help),
261	            Action::Format => {
262	                self.format = Some(match value.as_str() {
263	                    "csv" => Format::Csv,
264	                    "jsonl" => Format::Jsonl,
265	                    _ => {
266	                        let msg = format!("argument --format: invalid choice: '{value}'");
267	                        return Err(Stop::Error(msg));
268	                    }
269	                });
270	            }
271	            Action::Top => self.top = positive_int(&value).map_err(Stop::Error)?,
272	            Action::Json => self.json = true,
273	            Action::Strict => self.strict = true,
274	        }
275	        Ok(())
276	    }
277	
278	    /// FILE(nargs=None, 패턴 `-*A-*`)을 아직 못 받았으면 start 부터 맞춰 본다.
279	    fn consume_positionals(&mut self, start: usize) -> usize {
280	        if self.file.is_some() {
281	            return start;
282	        }
283	        let mut j = start;
284	        while self.pattern.get(j) == Some(&Pattern::DashDash) {
285	            j += 1;
286	        }
287	        if self.pattern.get(j) != Some(&Pattern::A) {
288	            return start;
289	        }
290	        j += 1;
291	        while self.pattern.get(j) == Some(&Pattern::DashDash) {
292	            j += 1;
293	        }
294	        // 위치 인자의 값에서는 처음 나온 '--' 하나를 뺀다
295	        let mut values: Vec<&OsString> = self.args[start..j].iter().collect();
296	        if let Some(i) = values.iter().position(|v| v.as_os_str() == "--") {
297	            values.remove(i);
298	        }
299	        self.file = values.first().map(|v| (*v).clone());
300	        j
301	    }
302	
303	    fn consume_optional(&mut self, start: usize) -> Result<usize, Stop> {
304	        let Some(mut t) = self.tuples[start].clone() else {
305	            return Ok(start + 1);
306	        };
307	        let mut actions: Vec<(Action, Option<String>)> = Vec::new();
308	        let stop;
309	        loop {
310	            let Some(action) = t.action else {
311	                self.extras = true;
312	                return Ok(start + 1);
313	            };
314	            match t.explicit.clone() {
315	                Some(explicit) => {
316	                    let single_dash = !t.option.starts_with("--");
317	                    if !action.takes_value() && single_dash && !explicit.is_empty() {
318	                        if t.sep || explicit.starts_with('-') {
319	                            return Err(Stop::Error(format!(
320	                                "ignored explicit argument '{explicit}'"
321	                            )));
322	                        }
323	                        actions.push((action, None));
324	                        let first = explicit.chars().next().unwrap_or('-');
325	                        let option = format!("-{first}");
326	                        match action_for(&option) {
327	                            Some(next) => {
328	                                let rest = &explicit[first.len_utf8()..];
329	                                t = OptTuple {
330	                                    action: Some(next),
331	                                    option,
332	                                    sep: rest.starts_with('='),
333	                                    explicit: if rest.is_empty() {
334	                                        None
335	                                    } else {
336	                                        Some(rest.strip_prefix('=').unwrap_or(rest).to_string())
337	                                    },
338	                                };
339	                            }
340	                            None => {
341	                                self.extras = true;
342	                                stop = start + 1;
343	                                break;
344	                            }
345	                        }
346	                    } else if action.takes_value() {
347	                        actions.push((action, Some(explicit)));
348	                        stop = start + 1;
349	                        break;
350	                    } else {
351	                        return Err(Stop::Error(format!(
352	                            "ignored explicit argument '{explicit}'"
353	                        )));
354	                    }
355	                }
356	                None => {
357	                    if action.takes_value() {
358	                        if self.pattern.get(start + 1) != Some(&Pattern::A) {
359	                            return Err(Stop::Error(format!(
360	                                "argument {}: expected one argument",
361	                                t.option
362	                            )));
363	                        }
364	                        let value = self.args[start + 1].to_string_lossy().into_owned();
365	                        actions.push((action, Some(value)));
366	                        stop = start + 2;
367	                    } else {
368	                        actions.push((action, None));
369	                        stop = start + 1;
370	                    }
371	                    break;
372	                }
373	            }
374	        }
375	        for (action, value) in actions {
376	            self.take_action(action, value)?;
377	        }
378	        Ok(stop)
379	    }
380	
381	    fn parse(&mut self) -> Result<(), Stop> {
382	        let option_indices: Vec<usize> = (0..self.args.len())
383	            .filter(|&i| self.pattern[i] == Pattern::O)
384	            .collect();
385	        let mut start = 0;
386	        if let Some(&max_option) = option_indices.last() {
387	            while start <= max_option {
388	                let next_option = option_indices
389	                    .iter()
390	                    .copied()
391	                    .find(|&i| i >= start)
392	                    .unwrap_or(max_option);
393	                if start != next_option {
394	                    let end = self.consume_positionals(start);
395	                    if end > start {
396	                        start = end;
397	                        continue;
398	                    }
399	                }
400	                if self.pattern[start] != Pattern::O {
401	                    self.extras = true;
402	                    start = next_option;
403	                }
404	                start = self.consume_optional(start)?;
405	            }
406	        }
407	        let stop = self.consume_positionals(start);
408	        if stop < self.args.len() {
409	            self.extras = true;
410	        }
411	        if self.file.is_none() {
412	            return Err(Stop::Error(
413	                "the following arguments are required: file".to_string(),
414	            ));
415	        }
416	        if self.extras {
417	            return Err(Stop::Error("unrecognized arguments".to_string()));
418	        }
419	        Ok(())
420	    }
421	}
422	
423	pub fn parse(args: &[OsString]) -> Outcome {
424	    let mut pattern = Vec::with_capacity(args.len());
425	    let mut tuples = Vec::with_capacity(args.len());
426	    let mut after_dashdash = false;
427	    for arg in args {
428	        if after_dashdash {
429	            pattern.push(Pattern::A);
430	            tuples.push(None);
431	        } else if arg.as_os_str() == "--" {
432	            after_dashdash = true;
433	            pattern.push(Pattern::DashDash);
434	            tuples.push(None);
435	        } else {
436	            let tuple = classify(&arg.to_string_lossy());
437	            pattern.push(if tuple.is_some() {
438	                Pattern::O
439	            } else {
440	                Pattern::A
441	            });
442	            tuples.push(tuple);
443	        }
444	    }
445	    let mut state = State {
446	        args,
447	        pattern,
448	        tuples,
449	        file: None,
450	        format: None,
451	        top: 10,
452	        json: false,
453	        strict: false,
454	        extras: false,
455	    };
456	    match state.parse() {
457	        Err(Stop::Help) => Outcome::Help,
458	        Err(Stop::Error(msg)) => Outcome::Error(msg),
459	        Ok(()) => Outcome::Run(Args {
460	            file: state.file.unwrap_or_default(),
461	            format: state.format,
462	            top: state.top,
463	            json: state.json,
464	            strict: state.strict,
465	        }),
466	    }
467	}
468	
469	#[cfg(test)]
470	mod tests {
471	    use super::*;
472	
473	    fn p(args: &[&str]) -> Outcome {
474	        let args: Vec<OsString> = args.iter().map(OsString::from).collect();
475	        parse(&args)
476	    }
477	
478	    fn run_args(file: &str, format: Option<Format>, top: u64, json: bool, strict: bool) -> Outcome {
479	        Outcome::Run(Args {
480	            file: file.into(),
481	            format,
482	            top,
483	            json,
484	            strict,
485	        })
486	    }
487	
488	    fn is_error(o: Outcome) -> bool {
489	        matches!(o, Outcome::Error(_))
490	    }
491	
492	    #[test]
493	    fn accepted_forms() {
494	        assert_eq!(p(&["a.csv"]), run_args("a.csv", None, 10, false, false));
495	        assert_eq!(
496	            p(&["--json", "--json", "a.csv"]),
497	            run_args("a.csv", None, 10, true, false)
498	        );
499	        assert_eq!(
500	            p(&["a", "--format", "csv", "--format", "jsonl"]),
501	            run_args("a", Some(Format::Jsonl), 10, false, false)
502	        );
503	        assert_eq!(
504	            p(&["--top=3", "a.csv"]),
505	            run_args("a.csv", None, 3, false, false)
506	        );
507	        assert_eq!(
508	            p(&["a.csv", "--top", "007"]),
509	            run_args("a.csv", None, 7, false, false)
510	        );
511	        assert_eq!(
512	            p(&["a.csv", "--top", "99999999999999999999999"]),
513	            run_args("a.csv", None, u64::MAX, false, false)
514	        );
515	        assert_eq!(
516	            p(&["--", "-x.csv"]),
517	            run_args("-x.csv", None, 10, false, false)
518	        );
519	        assert_eq!(
520	            p(&["a.csv", "--"]),
521	            run_args("a.csv", None, 10, false, false)
522	        );
523	        assert_eq!(p(&["--", "--"]), run_args("--", None, 10, false, false));
524	        assert_eq!(
525	            p(&["-5", "--strict"]),
526	            run_args("-5", None, 10, false, true)
527	        );
528	        assert_eq!(p(&["-", "--strict"]), run_args("-", None, 10, false, true));
529	        assert_eq!(p(&["-a b"]), run_args("-a b", None, 10, false, false));
530	        assert_eq!(p(&["-٣"]), run_args("-٣", None, 10, false, false));
531	        assert_eq!(p(&[""]), run_args("", None, 10, false, false));
532	    }
533	
534	    #[test]
535	    fn errors_and_help() {
536	        assert!(is_error(p(&[])));
537	        assert!(is_error(p(&["a.csv", "--js"])));
538	        assert!(is_error(p(&["a.csv", "--top", "0"])));
539	        assert!(is_error(p(&["a.csv", "--top", "-5"])));
540	        assert!(is_error(p(&["a.csv", "--top", "٣"])));
541	        assert!(is_error(p(&["a.csv", "--top", &"1".repeat(4301)])));
542	        assert!(is_error(p(&["a.csv", "--top"])));
543	        assert!(is_error(p(&["a.csv", "--top="])));
544	        assert!(is_error(p(&["a.csv", "--format", "tsv"])));
545	        assert!(is_error(p(&["a.csv", "--format", "--json"])));
546	        assert!(is_error(p(&["a.csv", "--json=1"])));
547	        assert!(is_error(p(&["a.csv", "b.csv"])));
548	        assert!(is_error(p(&["--", "a.csv", "--json"])));
549	        assert!(is_error(p(&["a.csv", "-x"])));
550	        assert!(is_error(p(&["a.csv", "-h=1"])));
551	        assert!(is_error(p(&["a.csv", "--top", "0", "--help"])));
552	        assert_eq!(p(&["a.csv", "--help", "--top", "0"]), Outcome::Help);
553	        assert_eq!(p(&["--js", "-h"]), Outcome::Help);
554	        assert_eq!(p(&["-hx"]), Outcome::Help);
555	        assert_eq!(
556	            p(&[]),
557	            Outcome::Error("the following arguments are required: file".into())
558	        );
559	    }
560	}
