1	//! logstat: CSV·JSON Lines 접근 로그를 요약한다(python_src/logstat.py 의 Rust 이식).
2	//!
3	//! `run` 은 입출력 없이 (종료 코드, stdout, stderr)를 돌려주는 순수 함수이고, main.rs 가 파일과 표준 출력을 다룬다.
4	//! stdout 은 WTF-8 바이트다. JSON 의 짝 없는 서로게이트(`"\ud800"`)가 경로로 출력되면 UTF-8 이 아니게 되고,
5	//! 그 처리는 main.rs 가 한다(Python 은 그 경우 stdout 에 쓰다가 UnicodeEncodeError 로 끝난다).
6	
7	pub mod cli;
8	pub mod csv;
9	pub mod help;
10	pub mod json;
11	pub mod output;
12	pub mod record;
13	pub mod ts;
14	
15	use std::collections::HashMap;
16	
17	use output::{error_rate, json_string, py_repr};
18	use record::Record;
19	
20	pub const EXIT_OK: i32 = 0;
21	pub const EXIT_INPUT_ERROR: i32 = 1;
22	pub const EXIT_USAGE_ERROR: i32 = 2;
23	
24	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
25	pub enum Format {
26	    Csv,
27	    Jsonl,
28	}
29	
30	pub struct TopPath {
31	    pub path: Vec<u8>,
32	    pub count: usize,
33	    pub error_rate: String,
34	    pub p50: f64,
35	    pub p95: f64,
36	}
37	
38	pub struct Summary {
39	    pub records: usize,
40	    pub skipped: usize,
41	    pub first: Option<i64>,
42	    pub last: Option<i64>,
43	    /// 넘침 없는 합(레코드당 최대 10^12)
44	    pub bytes: u128,
45	    /// 2xx, 3xx, 4xx, 5xx
46	    pub status: [usize; 4],
47	    pub methods: Vec<(&'static str, usize)>,
48	    pub latency: Option<[f64; 3]>,
49	    pub peak: Option<(String, usize)>,
50	    pub top: Vec<TopPath>,
51	}
52	
53	/// 안정 정렬. -0.0 과 0.0 은 같은 값으로 보아 입력 순서를 지킨다(Python sorted 와 같음).
54	fn sorted(mut values: Vec<f64>) -> Vec<f64> {
55	    values.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
56	    values
57	}
58	
59	/// nearest-rank: k = ceil(p * n / 100), 정수로만 계산
60	fn nearest_rank(sorted_values: &[f64], p: usize) -> f64 {
61	    let k = (p * sorted_values.len() + 99) / 100;
62	    sorted_values[k.max(1) - 1]
63	}
64	
65	/// Python sum() 처럼 넘치지 않게 u128 로 더한다(u64 는 약 1,850만 × 10^12 에서 넘친다)
66	fn total_bytes(values: impl Iterator<Item = i64>) -> u128 {
67	    values.map(|b| b as u128).sum()
68	}
69	
70	pub fn summarize(records: &[Record], skipped: usize, top_n: u64) -> Summary {
71	    let mut status = [0usize; 4];
72	    let mut methods: HashMap<&'static str, usize> = HashMap::new();
73	    let mut minutes: HashMap<i64, usize> = HashMap::new();
74	    let mut by_path: HashMap<&[u8], Vec<&Record>> = HashMap::new();
75	    for r in records {
76	        // 1xx 는 어디에도 세지 않는다
77	        if let Some(slot) = usize::try_from(r.status / 100 - 2)
78	            .ok()
79	            .and_then(|i| status.get_mut(i))
80	        {
81	            *slot += 1;
82	        }
83	        *methods.entry(r.method).or_default() += 1;
84	        *minutes.entry(ts::minute_index(r.ts)).or_default() += 1;
85	        by_path.entry(&r.path).or_default().push(r);
86	    }
87	    let mut methods: Vec<(&'static str, usize)> = methods.into_iter().collect();
88	    methods.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
89	
90	    let mut paths: Vec<(&[u8], Vec<&Record>)> = by_path.into_iter().collect();
91	    paths.sort_by(|a, b| b.1.len().cmp(&a.1.len()).then(a.0.cmp(b.0)));
92	    let take = usize::try_from(top_n).unwrap_or(usize::MAX);
93	    let top = paths
94	        .into_iter()
95	        .take(take)
96	        .map(|(path, rows)| {
97	            let values = sorted(rows.iter().map(|r| r.latency_ms).collect());
98	            let errors = rows.iter().filter(|r| r.status >= 500).count();
99	            TopPath {
100	                path: path.to_vec(),
101	                count: rows.len(),
102	                error_rate: error_rate(errors, rows.len()),
103	                p50: nearest_rank(&values, 50),
104	                p95: nearest_rank(&values, 95),
105	            }
106	        })
107	        .collect();
108	
109	    // 개수가 가장 많은 분, 같으면 이른 분
110	    let peak = minutes
111	        .into_iter()
112	        .min_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)))
113	        .map(|(minute, count)| (ts::minute_key(minute * 60_000_000), count));
114	    let latencies = sorted(records.iter().map(|r| r.latency_ms).collect());
115	    Summary {
116	        records: records.len(),
117	        skipped,
118	        first: records.iter().map(|r| r.ts).min(),
119	        last: records.iter().map(|r| r.ts).max(),
120	        bytes: total_bytes(records.iter().map(|r| r.bytes)),
121	        status,
122	        methods,
123	        latency: if records.is_empty() {
124	            None
125	        } else {
126	            Some([50, 95, 99].map(|p| nearest_rank(&latencies, p)))
127	        },
128	        peak,
129	        top,
130	    }
131	}
132	
133	const STATUS_KEYS: [&str; 4] = ["2xx", "3xx", "4xx", "5xx"];
134	
135	pub fn format_text(s: &Summary) -> Vec<u8> {
136	    let range = match (s.first, s.last) {
137	        (Some(first), Some(last)) => {
138	            format!("{} .. {}", ts::isoformat(first), ts::isoformat(last))
139	        }
140	        _ => "-".to_string(),
141	    };
142	    let status: Vec<String> = STATUS_KEYS
143	        .iter()
144	        .zip(s.status)
145	        .map(|(k, v)| format!("{k}={v}"))
146	        .collect();
147	    let methods: Vec<String> = s.methods.iter().map(|(k, v)| format!("{k}={v}")).collect();
148	    let methods = if methods.is_empty() {
149	        "-".to_string()
150	    } else {
151	        methods.join(" ")
152	    };
153	    let latency = match s.latency {
154	        Some([p50, p95, p99]) => format!(
155	            "p50={} p95={} p99={}",
156	            py_repr(p50),
157	            py_repr(p95),
158	            py_repr(p99)
159	        ),
160	        None => "-".to_string(),
161	    };
162	    let peak = match &s.peak {
163	        Some((minute, count)) => format!("{minute} {count}"),
164	        None => "-".to_string(),
165	    };
166	    let mut out = format!(
167	        "records: {}\nskipped: {}\nrange: {range}\nbytes: {}\nstatus: {}\nmethods: {methods}\n\
168	         latency_ms: {latency}\npeak_minute: {peak}\ntop_paths:\n",
169	        s.records,
170	        s.skipped,
171	        s.bytes,
172	        status.join(" ")
173	    )
174	    .into_bytes();
175	    for t in &s.top {
176	        out.extend_from_slice(
177	            format!(
178	                "{}\t{}\t{}\t{}\t",
179	                t.count,
180	                t.error_rate,
181	                py_repr(t.p50),
182	                py_repr(t.p95)
183	            )
184	            .as_bytes(),
185	        );
186	        out.extend_from_slice(&t.path);
187	        out.push(b'\n');
188	    }
189	    out
190	}
191	
192	fn json_opt_string(out: &mut Vec<u8>, s: Option<String>) {
193	    match s {
194	        Some(s) => json_string(out, s.as_bytes()),
195	        None => out.extend_from_slice(b"null"),
196	    }
197	}
198	
199	/// `json.dumps(summary, ensure_ascii=False, separators=(",", ":")) + "\n"`
200	pub fn format_json(s: &Summary) -> Vec<u8> {
201	    let mut out = Vec::new();
202	    out.extend_from_slice(
203	        format!(
204	            "{{\"records\":{},\"skipped\":{},\"first\":",
205	            s.records, s.skipped
206	        )
207	        .as_bytes(),
208	    );
209	    json_opt_string(&mut out, s.first.map(ts::isoformat));
210	    out.extend_from_slice(b",\"last\":");
211	    json_opt_string(&mut out, s.last.map(ts::isoformat));
212	    out.extend_from_slice(format!(",\"bytes\":{},\"status\":{{", s.bytes).as_bytes());
213	    let status: Vec<String> = STATUS_KEYS
214	        .iter()
215	        .zip(s.status)
216	        .map(|(k, v)| format!("\"{k}\":{v}"))
217	        .collect();
218	    out.extend_from_slice(status.join(",").as_bytes());
219	    out.extend_from_slice(b"},\"methods\":{");
220	    let methods: Vec<String> = s
221	        .methods
222	        .iter()
223	        .map(|(k, v)| format!("\"{k}\":{v}"))
224	        .collect();
225	    out.extend_from_slice(methods.join(",").as_bytes());
226	    out.extend_from_slice(b"},\"latency_ms\":");
227	    match s.latency {
228	        Some([p50, p95, p99]) => out.extend_from_slice(
229	            format!(
230	                "{{\"p50\":{},\"p95\":{},\"p99\":{}}}",
231	                py_repr(p50),
232	                py_repr(p95),
233	                py_repr(p99)
234	            )
235	            .as_bytes(),
236	        ),
237	        None => out.extend_from_slice(b"null"),
238	    }
239	    out.extend_from_slice(b",\"peak_minute\":");
240	    match &s.peak {
241	        Some((minute, count)) => {
242	            out.extend_from_slice(b"{\"minute\":");
243	            json_string(&mut out, minute.as_bytes());
244	            out.extend_from_slice(format!(",\"count\":{count}}}").as_bytes());
245	        }
246	        None => out.extend_from_slice(b"null"),
247	    }
248	    out.extend_from_slice(b",\"top_paths\":[");
249	    for (i, t) in s.top.iter().enumerate() {
250	        if i > 0 {
251	            out.push(b',');
252	        }
253	        out.extend_from_slice(b"{\"path\":");
254	        json_string(&mut out, &t.path);
255	        out.extend_from_slice(
256	            format!(
257	                ",\"count\":{},\"error_rate\":\"{}\",\"p50\":{},\"p95\":{}}}",
258	                t.count,
259	                t.error_rate,
260	                py_repr(t.p50),
261	                py_repr(t.p95)
262	            )
263	            .as_bytes(),
264	        );
265	    }
266	    out.extend_from_slice(b"]}\n");
267	    out
268	}
269	
270	/// 입출력 없는 본체. (종료 코드, stdout, stderr)
271	pub fn run(
272	    text: &str,
273	    fmt: Format,
274	    top_n: u64,
275	    as_json: bool,
276	    strict: bool,
277	) -> (i32, Vec<u8>, Vec<u8>) {
278	    let rows = match fmt {
279	        Format::Csv => {
280	            // 파일 끝까지 읽은 뒤에 헤더·긴 필드 오류를 먼저 본다(--strict 의 앞선 잘못된 레코드보다 우선)
281	            let (rows, header_error) = record::read_csv(text);
282	            if let Some(err) = header_error {
283	                return (
284	                    EXIT_INPUT_ERROR,
285	                    Vec::new(),
286	                    format!("logstat: error: {err}\n").into_bytes(),
287	                );
288	            }
289	            rows
290	        }
291	        Format::Jsonl => record::read_jsonl(text),
292	    };
293	    let mut records = Vec::new();
294	    let mut skipped = 0;
295	    for (number, item) in rows {
296	        match item {
297	            Ok(r) => records.push(r),
298	            Err(reason) => {
299	                if strict {
300	                    return (
301	                        EXIT_INPUT_ERROR,
302	                        Vec::new(),
303	                        format!("logstat: error: record {number}: {reason}\n").into_bytes(),
304	                    );
305	                }
306	                skipped += 1;
307	            }
308	        }
309	    }
310	    let summary = summarize(&records, skipped, top_n);
311	    let out = if as_json {
312	        format_json(&summary)
313	    } else {
314	        format_text(&summary)
315	    };
316	    (EXIT_OK, out, Vec::new())
317	}
318	
319	#[cfg(test)]
320	mod tests {
321	    use super::*;
322	
323	    const HEADER: &str = "ts,method,path,status,bytes,latency_ms\n";
324	
325	    #[test]
326	    fn query_string_is_dropped() {
327	        let text = format!("{HEADER}2026-10-29T00:00:00Z,GET,/a?x=1,200,1,1\n2026-10-29T00:00:00Z,GET,/a?y=2,200,1,1\n");
328	        let (_, out, _) = run(&text, Format::Csv, 10, false, false);
329	        assert!(String::from_utf8(out)
330	            .unwrap()
331	            .ends_with("2\t0.0%\t1.0\t1.0\t/a\n"));
332	    }
333	
334	    #[test]
335	    fn timezone_and_peak_minute() {
336	        let text = format!(
337	            "{HEADER}2026-10-29T09:00:30+09:00,GET,/a,200,1,1\n2026-10-29T00:00:10Z,GET,/a,200,1,1\n\
338	             2026-10-29T00:01:00Z,GET,/a,200,1,1\n"
339	        );
340	        let out = String::from_utf8(run(&text, Format::Csv, 10, false, false).1).unwrap();
341	        assert!(out.contains("range: 2026-10-29T00:00:10+00:00 .. 2026-10-29T00:01:00+00:00\n"));
342	        assert!(out.contains("peak_minute: 2026-10-29T00:00Z 2\n"));
343	    }
344	
345	    #[test]
346	    fn empty_input_json() {
347	        let (_, out, _) = run("", Format::Csv, 10, true, false);
348	        assert_eq!(
349	            String::from_utf8(out).unwrap(),
350	            "{\"records\":0,\"skipped\":0,\"first\":null,\"last\":null,\"bytes\":0,\
351	             \"status\":{\"2xx\":0,\"3xx\":0,\"4xx\":0,\"5xx\":0},\"methods\":{},\"latency_ms\":null,\
352	             \"peak_minute\":null,\"top_paths\":[]}\n"
353	        );
354	    }
355	
356	    #[test]
357	    fn strict_reasons() {
358	        let cases = [
359	            ("{\"ts\":\"2026-10-29T00:00:00Z\",\"method\":\"GET\",\"path\":\"/\",\"status\":true,\"bytes\":1,\"latency_ms\":1}", "bad status"),
360	            ("{\"ts\":\"2026-10-29T00:00:00Z\",\"method\":\"GET\",\"path\":\"/\",\"status\":200,\"bytes\":1,\"latency_ms\":NaN}", "bad latency_ms"),
361	            ("{\"ts\":\"2026-02-30T00:00:00Z\",\"method\":\"GET\",\"path\":\"/\",\"status\":200,\"bytes\":1,\"latency_ms\":1}", "bad ts"),
362	            ("{\"ts\":\"2026-10-29T00:00:00Z\",\"method\":\"GET\",\"path\":\"/\",\"status\":200,\"bytes\":1}", "missing field: latency_ms"),
363	            ("[1]", "not an object"),
364	            ("{", "invalid json"),
365	        ];
366	        for (line, reason) in cases {
367	            let got = run(&format!("{line}\n"), Format::Jsonl, 10, false, true);
368	            assert_eq!(
369	                got,
370	                (
371	                    1,
372	                    Vec::new(),
373	                    format!("logstat: error: record 1: {reason}\n").into_bytes()
374	                )
375	            );
376	        }
377	    }
378	
379	    #[test]
380	    fn huge_field_beats_strict() {
381	        let text = format!(
382	            "{HEADER}x\n2026-10-29T00:00:00Z,GET,/{},200,1,1\n",
383	            "x".repeat(131_072)
384	        );
385	        assert_eq!(
386	            run(&text, Format::Csv, 10, false, true),
387	            (
388	                1,
389	                Vec::new(),
390	                b"logstat: error: record 2: csv field too large\n".to_vec()
391	            )
392	        );
393	    }
394	
395	    #[test]
396	    fn negative_zero_keeps_input_order() {
397	        let line = |lat: &str| {
398	            format!("{{\"ts\":\"2026-10-29T00:00:00Z\",\"method\":\"GET\",\"path\":\"/\",\"status\":200,\"bytes\":1,\"latency_ms\":{lat}}}\n")
399	        };
400	        let a = run(
401	            &(line("-0.0") + &line("0.0")),
402	            Format::Jsonl,
403	            10,
404	            false,
405	            false,
406	        )
407	        .1;
408	        assert!(String::from_utf8(a).unwrap().contains("p50=-0.0 p95=0.0"));
409	        let b = run(
410	            &(line("0.0") + &line("-0.0")),
411	            Format::Jsonl,
412	            10,
413	            false,
414	            false,
415	        )
416	        .1;
417	        assert!(String::from_utf8(b).unwrap().contains("p50=0.0 p95=-0.0"));
418	    }
419	
420	    #[test]
421	    fn bytes_sum_does_not_overflow() {
422	        let values = std::iter::repeat(1_000_000_000_000).take(20_000_000);
423	        assert_eq!(total_bytes(values), 20_000_000_000_000_000_000);
424	    }
