        let get = |name: &str| {
            let i = FIELDS.iter().position(|f| *f == name).unwrap_or(0);
            row[index[i]].as_str()
        };
        out.push((number, record_from_strings(get)));
    }
    (out, None)
}

pub fn read_jsonl(text: &str) -> Vec<Row> {
    let mut out = Vec::new();
