        }
        number += 1;
        let item = match json::loads(line) {
            Err(_) => Err(bad("invalid json")),
            Ok(Parsed::NotObject) => Err(bad("not an object")),
            Ok(Parsed::Object(obj)) => record_from_json(&obj),
        };
        out.push((number, item));
    }
    out
}

